function overlayBdbhTranslations(mod, translated){
  if(!mod||!window.ScripturaBDBHptFormat)
    throw new Error("BDB-H/PT: módulo de origem ou formatador canônico indisponível");
  const originalLength=mod.sourceRecords.length;
  for(const item of translated){
    if(item.translation_status!=="TRADUCAO_INTEGRAL")
      throw new Error("BDB-H/PT: não publicar tradução incompleta "+item.ordinal);
    const cardExpression=new RegExp('<article id="([^"]+)"[^>]*data-bdbh-ordinal="'+item.ordinal+'"[^>]*>');
    const match=mod.cardsHtml.match(cardExpression);
    if(!match)throw new Error("BDB-H/PT: artigo ausente "+item.ordinal);
    const cardId=match[1],start=mod.cardsHtml.indexOf(match[0]),end=mod.cardsHtml.indexOf("</article>",start);
    if(end<0)throw new Error("BDB-H/PT: artigo não fechado "+item.ordinal);
    const card=mod.cardsHtml.slice(start,end+10);
    const english=/<section class="entry-section" lang="en">[\s\S]*?<\/section>/g;
    const hits=card.match(english);
    if(!hits||hits.length!==1)throw new Error("BDB-H/PT: seção inglesa original ambígua "+item.ordinal);
    const status=item.collation_status==="COLACIONADO"?"COLACIONADO":"REVISAO";
    const label=status==="COLACIONADO"
      ?"Tradução portuguesa — colacionada (auditoria pendente)"
      :"Tradução portuguesa — revisão editorial pendente";
    let html=item.html;
    if(item.ordinal===146){
      const from='<a data-ref="Exodus 35-40" href="/Exodus.35-40">35–40</a>';
      if(!html.includes(from))throw Error("Fonte Exodus 35–40 ausente");
      html=html.replace(from,"__BDB_PT_EXO_RANGE__");
    }
    let portuguese=window.ScripturaBDBHptFormat.format(html,item);
    if(item.ordinal===146){
      // Êx 35–40: capítulo inicial como destino, intervalo esclarecido no popup.
      const to='<a class="reference-link bdbh-pt-link bdbh-pt-bible-link tooltip-trigger" href="#escrituras/UXLC/EXO.35.1" data-ref="Exodus 35-40" data-bdbh-source-href="/Exodus.35-40" data-bdbh-citation="Êx 35–40" aria-label="Êxodo, capítulos 35 a 40" data-tooltip-type="abbr" data-tooltip-label="Êx 35–40" data-tooltip-text="Êxodo, capítulos 35 a 40. Este link abre o início do capítulo 35 no leitor hebraico do Scriptura Lexicon; a referência histórica abrange também os capítulos 36 a 40.">Êx 35–40</a>';
      if(!portuguese.includes("__BDB_PT_EXO_RANGE__"))throw Error("Substituição de faixa ausente");
      portuguese=portuguese.replace("__BDB_PT_EXO_RANGE__",to);
    }
    if(item.ordinal===121){
      // Colação: גרף está no texto visível; data-ref original remete incorretamente a גֹּ֫רֶן.
      // Preservar data-ref e o href original em data-bdbh-source-href; corrigir apenas o destino pesquisável.
      const old='data-bdbh-lemma="גֹּ֫רֶן"';
      if(!portuguese.includes(old))throw Error('BDB-H/PT: remissão 121 não comprovada');
      portuguese=portuguese.replace(old,'data-bdbh-lemma="גָּרַף"')
        .replace('Remissão ao verbete BDB-H גֹּ֫רֶן.','Remissão ao verbete BDB-H גָּרַף.');
    }
    if(item.ordinal===131){
      // Divergência inequívoca na fonte: o rótulo impresso é Ex 20:24 (altar de terra),
      // mas data-ref e href de Sefaria apontam para Exodus 20:21. Fonte e rastro preservados.
      const match=portuguese.match(/<a\b[^>]*data-ref="Exodus 20:21"[^>]*>[\s\S]*?<\/a>/);
      if(!match||!match[0].includes('#escrituras/UXLC/EXO.20.21'))
        throw Error("BDB-H/PT: incongruência Êx 20.24 não localizável");
      const patch=match[0].replace('#escrituras/UXLC/EXO.20.21','#escrituras/UXLC/EXO.20.24')
        .replaceAll('Êx 20.21','Êx 20.24')
        .replaceAll('versículo 21','versículo 24');
      if(patch.includes("Êx 20.21")||patch.includes("EXO.20.21")||patch.includes("versículo 21"))
        throw Error("BDB-H/PT: remissão Êx 20.24 não normalizada");
      portuguese=portuguese.replace(match[0],patch);
    }
    // Divergências da indexação Sefaria: o data-ref documental permanece intacto;
    // apenas rótulo, tooltip e destino público refletem a citação impressa.
    if(item.ordinal===149||item.ordinal===152){
      const sourceRef=item.ordinal===149?"Nehemiah 7:60":"Numbers 7:18";
      const oldTarget=item.ordinal===149?"#escrituras/UXLC/NEH.7.60":"#escrituras/UXLC/NUM.7.18";
      const newTarget=item.ordinal===149?"#escrituras/UXLC/NEH.7.61":"#escrituras/UXLC/NEH.7.18";
      const oldLabel=item.ordinal===149?"Ne 7.60":"Nm 7.18";
      const newLabel=item.ordinal===149?"Ne 7.61":"Ne 7.18";
      const a=portuguese.match(new RegExp('<a\\b[^>]*data-ref="'+sourceRef+'"[^>]*>[\\s\\S]*?<\\/a>'));
      if(!a||!a[0].includes(oldTarget))throw Error("BDB-H/PT: divergência de referência não localizável: "+item.ordinal);
      let target=a[0].replaceAll(oldTarget,newTarget).replaceAll(oldLabel,newLabel);
      if(item.ordinal===149)target=target.replaceAll("versículo 60","versículo 61");
      else target=target.replaceAll("Números, capítulo 7","Neemias, capítulo 7");
      if(target.includes(oldTarget)||target.includes(oldLabel))throw Error("BDB-H/PT: remissão não normalizada");
      portuguese=portuguese.replace(a[0],target);
    }
    // Ordinal 165: o segundo rótulo impresso é אדון, mas o data-ref Sefaria
    // repete erroneamente אֲדֹנִירָם. Preservar os metadados da fonte,
    // corrigir APENAS a pesquisa interna e seu popup.
    if(item.ordinal===165){
      const match=portuguese.match(/<a\b[^>]*data-ref="BDB, אֲדֹנִירָם"[^>]*>אדון<\/a>/);
      if(!match||!match[0].includes('data-bdbh-lemma="אֲדֹנִירָם"'))throw Error("BDB-H/PT: remissão do ordinal 165 não comprovada");
      const fixed=match[0].replace('data-bdbh-lemma="אֲדֹנִירָם"','data-bdbh-lemma="אָדוֹן"')
        .replace('Remissão ao verbete BDB-H אֲדֹנִירָם.', 'Remissão ao verbete BDB-H אָדוֹן.');
      if(!fixed.includes('data-bdbh-lemma="אָדוֹן"'))throw Error("BDB-H/PT: correção do ordinal 165 falhou");
      portuguese=portuguese.replace(match[0],fixed);
    }
    const ptSection='<section class="entry-section bdbh-pt-section" lang="pt-BR"'
      +' data-bdbh-ui="2026-11-15" data-bdbh-pt-state="'+status+'">'
      +'<div class="section-title">'+label+'</div>'
      +'<div class="entry-text">'+portuguese+'</div></section>';
    // Substituição, NÃO sobreposição: o inglês permanece só em sourceRecords.
    const clean=card.replace(english,ptSection);
    if(clean.includes('Fonte original (inglês) — Brown–Driver–Briggs'))
      throw new Error("BDB-H/PT: inglês indevidamente visível em "+item.ordinal);
    mod.cardsHtml=mod.cardsHtml.slice(0,start)+clean+mod.cardsHtml.slice(end+10);
    const token='data-target="'+cardId+'"',at=mod.rowsHtml.indexOf(token);
    if(at<0)throw new Error("BDB-H/PT: linha de pesquisa ausente "+item.ordinal);
    const rowStart=mod.rowsHtml.lastIndexOf("<tr ",at),rowEnd=mod.rowsHtml.indexOf("</tr>",at)+5;
    if(rowStart<0||rowEnd<5)throw new Error("BDB-H/PT: limites de linha inválidos");
    let row=mod.rowsHtml.slice(rowStart,rowEnd);
    const esc=v=>v.replace(/&/g,"&amp;").replace(/"/g,"&quot;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
    if(!row.includes("data-bdbh-pt-row")){
      row=row.replace('class="search-row"','class="search-row" data-bdbh-pt-row="'+status+'"');
      row=row.replace(/data-search="([^"]*)"/,(m,s)=>'data-search="'+s+" "+esc(item.preview)+'"');
      row=row.replace(/<td lang="en">[\s\S]*?<\/td>/,'<td lang="pt-BR">'+esc(item.preview)+'</td>');
      mod.rowsHtml=mod.rowsHtml.slice(0,rowStart)+row+mod.rowsHtml.slice(rowEnd);
    }
  }
  if(mod.sourceRecords.length!==originalLength)
    throw new Error("BDB-H/PT: número de fontes inglesas alterado");
}
overlayBdbhTranslations(window.ScripturaLexicons && window.ScripturaLexicons["bdbh-batch-002"], window.ScripturaBDBHpt.batch002.records);
